// ?checkForAdjust@Rva003D6210@@QAE_NABUPathfindMovementProfile@@H_NHHHPAUCoord3D@@1@Z
// partial score=0.85 date=2026-09-29
// Probe TU for retail 0x003D6210 (181 bytes).
//
// IDENTITY: this is Pathfinder::checkForPossible, the BFME eight-argument
// overload.  targets/game/reverse/identity_evidence/003d6210-checkForPossible.md
// carries the proof: the byte-matched
// game/GameEngine/Source/GameLogic/AI/PathfinderAdjustToPossibleDestination.cpp
// declares `Bool Pathfinder::checkForPossible(const PathfindMovementProfile &,
// Int, Bool, Int, Int, PathfindLayerEnum, Coord3D *, Bool)` and calls it
// four times through ILT 0x00018BE7 -> 0x003D6210.  The class below is spelled
// Rva003D6210 only so probe.py has a unique mangled name; landing means moving
// the body to game/GameEngine/Source/GameLogic/AI/ as Pathfinder::checkForPossible
// and renaming the two `Rva003D6210` occurrences.  The old `checkForAdjust`
// label is REJECTED: nothing carries it, and it does not fit the body.
//
// MEASURED THIS SESSION (probe.py, relocations masked): 181/181 bytes,
// shape 1.000, 22 non-relocation differences -- every one of them the
// ESI/EDI callee-saved choice (this=ESI / m_zoneManager=EDI here, retail the
// other way round), plus the two a1/a2 operand loads of the final call
// (see below).  That is up from 178 bytes / 64 differences at score 0.65.
//
// FOUR LEVERS CLOSED SINCE 0.65 (all measured, do not retry):
//
//  1. The bit-21 test is `shr ecx,0x15; test cl,1` (5 bytes) in retail, NOT
//     `test ecx,0x200000` (6 bytes).  The winning spelling is
//         if ((unsigned char)(flags >> 21) & 1)
//     The `(unsigned char)` cast is load bearing: `(flags >> 21) & 1` and the
//     union bitfield `cell->m_bit21` (signed or unsigned) all still fold to
//     the 6-byte `test`.  The same expression is already proven in the
//     byte-matched sibling body game/GameEngine/Source/Common/Rva003D65D0Apply.cpp
//     (+0x2c), which reads the identical PathfindCell word at +0x0c.
//
//  2. `zone` must be a 32-bit `Int`, not `zoneStorageType`.  Both zone-manager
//     calls return 16-bit, and retail zero-extends each result
//     (`movzx eax,ax` at +0x71 and +0x7f) because it then compares it as a
//     32-bit value against `expectedZone` (+0x82).  A 16-bit local makes both
//     movzx disappear and shortens the body.
//
//  3. The zone-mismatch reject needs the OPPOSITE spelling from the early
//     rejects.  `if (expectedZone != zone) goto lateFailure;` makes MSVC
//     invert the branch: it emits `je <success>` and inlines a duplicated
//     false epilogue.  Retail is `cmp/jne <shared tail>` with the SUCCESS
//     path falling through, so the test must be written positively --
//     `if (expectedZone == zone) { adjustCoordToCell(...); return true; }`
//     -- while the bit21/terrainOnly reject stays a `goto lateFailure;` onto
//     the single trailing `return false;` at +0xad.  This alone was worth
//     45 -> 22 differences.
//
//  4. Retail's final call passes the PROFILE as adjustCoordToCell's first
//     coordinate: +0x97 loads [esp+0x24] = arg1, not [esp+0x14] = arg5
//     (cellY).  So the call really is
//         adjustCoordToCell( <profile address>, cellX, center, *dest, layer )
//     and cellY is never forwarded -- a copy/paste artefact of the BFME
//     port.  It is load bearing for the bytes, so the a1/a2 displacement
//     pair at +0x91/+0x97 is still 4 bytes out until the allocator can be
//     persuaded to keep the profile's live range short.  Do NOT simply
//     "correct" it to cellY: that compiles, but the operands then differ
//     from retail's.
//
// REMAINING RESIDUE (22 bytes, the class docs/shape_levers.md calls
// unlandable): targets/game/reverse/analysis/register_mirror_experiments.md
// Finding 3 says a `lea this+N` sub-object used as the receiver of 2+ calls
// outranks `this` for ESI; retail here has that behaviour (this=EDI,
// m_zoneManager=ESI) and we do not.  Its follow-up R2b refutes every
// respelling -- use-count padding, first-use order, folded uses, plain
// pointer members -- and says the fix would be a MISSING call or field read,
// but probe shape 1.000 says the instruction stream is already identical, so
// there is nothing missing.  Measured here and all equal to the same 22
// differences, i.e. confirmed inert: explicit zone-manager pointer local
// (`PathfindZoneManager *zm = &m_zoneManager`), a zone-manager reference
// local (worse: 183 bytes), an explicit `Pathfinder *self = this` (this goes
// to EBX), and passing the profile as a1 via `reinterpret_cast<Int>(&profile)`
// or `(Int)(size_t)&profile` (worse: 181 bytes but 129 differences, the
// extended profile live range pushes `this` into EBX and hoists the profile
// load, restructuring the whole body).
// tools/shape_family_levers.py --families register,sib,bool,test,copy,store,loop,branch,constant,frame
// reports no applicable automatic lever.
//
// probe: python3 tools/probe.py <this file> "?checkForAdjust@Rva003D6210@@QAE_NABUPathfindMovementProfile@@H_NHHHPAUCoord3D@@1@Z" 0x003D6210
// cl: /O2 /Ob2 /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHsc

typedef int Int;
typedef bool Bool;
typedef unsigned short zoneStorageType;

struct Coord3D
{
	float x;
	float y;
	float z;
};

enum PathfindLayerEnum
{
	PATHFIND_LAYER_GROUND = 0
};

struct PathfindMovementProfile
{
	Int acceptableSurfaces;
	Bool crusher;
	Bool terrainOnly;
	unsigned char padding[2];
	Int layer;
};

class PathfindZoneManager
{
public:
	zoneStorageType getEffectiveZone(
		const PathfindMovementProfile &profile, zoneStorageType zone) const;
	zoneStorageType bfmeEffectiveTerrainZone(
		const PathfindMovementProfile &profile, zoneStorageType zone) const;
};

class PathfindCell
{
public:
	unsigned char m_pad00[8];
	zoneStorageType m_zone;

	private:
	unsigned short m_pad0a;

	public:
	union
	{
		unsigned int m_flags;
		struct
		{
			unsigned int m_type : 3;
			unsigned int m_unused0 : 18;
			unsigned int m_bit21 : 1;
			unsigned int m_unused1 : 10;
		};
	};
};

class Pathfinder
{
public:
	PathfindCell *getCell(PathfindLayerEnum layer, Int cellX, Int cellY);
	void adjustCoordToCell(Int cellX, Int cellY, Bool center,
		Coord3D &pos, PathfindLayerEnum layer);

protected:
	unsigned char m_pad[0xc9c];
	PathfindZoneManager m_zoneManager;
};

class Rva003D6210 : public Pathfinder
{
public:
	Bool checkForAdjust(const PathfindMovementProfile &profile,
		Int expectedZone, Bool center, Int cellX, Int cellY, Int layer,
		Coord3D *pos, Bool terrainZone);
};

Bool Rva003D6210::checkForAdjust(
	const PathfindMovementProfile &profile, Int expectedZone, Bool center,
	Int cellX, Int cellY, Int layer, Coord3D *pos, Bool terrainZone)
{
	PathfindCell *cell;
	unsigned int flags;
	unsigned int type;
	Int zone;

	cell = getCell((PathfindLayerEnum)layer, cellX, cellY);
	if (cell == 0)
		return false;

	flags = cell->m_flags;
	if (((flags >> 6) & 0x3f) != (unsigned int)layer)
 		return false;
	type = flags & 7;
	if (type == 4)
		return false;
	if (type == 5)
		return false;

	if ((unsigned char)(flags >> 21) & 1)
	{
		if (profile.terrainOnly)
			goto lateFailure;
	}

	zone = m_zoneManager.getEffectiveZone(profile,
		cell->m_zone);
	if (terrainZone)
		zone = m_zoneManager.bfmeEffectiveTerrainZone(profile,
			(zoneStorageType)zone);
	if (expectedZone == zone)
	{
		adjustCoordToCell(cellY, cellX, center, *pos,
			(PathfindLayerEnum)layer);
		return true;
	}

lateFailure:
	return false;
}
